import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname } from 'node:path'

const input = process.argv[2] ?? 'events.log'
const output = 'out/events.json'

const lines = readFileSync(input, 'utf8').split('\n').filter(line => line.trim() !== '')

const events = lines.map((line, index) => {
  const match = /^(\S+) (INFO|WARN|ERROR) (.+)$/.exec(line)
  if (match === null) {
    throw new Error('line ' + (index + 1) + ' does not match "<ISO8601-ts> <LEVEL> <message>": ' + JSON.stringify(line))
  }
  return { ts: match[1], level: match[2], message: match[3] }
})

mkdirSync(dirname(output), { recursive: true })
writeFileSync(output, JSON.stringify(events, null, 2) + '\n')

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname } from 'node:path'

const input = process.argv[2] ?? 'out/events.json'
const output = 'out/stats.json'

const events = JSON.parse(readFileSync(input, 'utf8'))

const total = events.length
const perLevel = { INFO: 0, WARN: 0, ERROR: 0 }
for (const event of events) {
  if (!(event.level in perLevel)) {
    throw new Error('unknown level ' + JSON.stringify(event.level))
  }
  perLevel[event.level] += 1
}
const errorRate = Number((perLevel.ERROR / total).toFixed(3))

const stats = { total, perLevel, errorRate }

mkdirSync(dirname(output), { recursive: true })
writeFileSync(output, JSON.stringify(stats, null, 2) + '\n')

